actions.action:
sc_limit: f.sc_limit;

prenes_hodnoty(sc_limit)
postav_menu()
changeCaseProperty("title").about { "Konfigurácia schvaľovania" }
changeCaseProperty("color").about { "blue" }

document.function:
{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by pri kazdej verzii vznikla dalsia.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}

{ ->
    // Jedna polozka, typu TASK zuzeneho na `transitionId` - to je sposob, ako
    // spravit "single task" zobrazenie: klik v menu otvori rovno formular
    // a nie zoznam s jednym riadkom (cheatsheet, Menu a zobrazenia).
    //
    // DOPYT SA ZUZUJE LEN NA `transitionId`. Task dokument v indexe
    // `processIdentifier` NEMA - nesie `processId`, teda stringId verzie siete,
    // ktory sa pri kazdom re-importe meni. Dopyt s `processIdentifier` teda
    // nenajde nikdy nic a obrazovka je prazdna, hoci case aj uloha existuju.
    // Presne to sa tu stalo: "nastavenia nefunguju, nie je tam ziaden pripad".
    // Id prechodu je naprieč sietami unikatne. Zuzuje sa ale este na `processId`
    // TEJTO verzie siete: `bootstrapCase` s `rebuildOnNewVersion` zaklada jeden
    // case NA VERZIU, takze po druhom re-importe by zobrazenie ukazalo dva
    // riadky "Konfigurácia schvaľovania" a clovek by nevedel, ktory je ten
    // platny. `processId` sa pri kazdom importe meni - a to je tu v poriadku,
    // lebo polozku menu prestavia ta ista akcia, ktora nove `processId` pozna.
    def id = "sc_nastavenia_view"
    def siet = "nastavenia/sc_nastavenia"
    def nazov = i18n("Konfigurácia schvaľovania", ["en": "Approval settings"])
    try {
        def existing = menu_item(id)
        if (existing != null) {
            // Update cesta `createOrUpdateMenuItem` nefunguje, polozka sa vzdy
            // zahodi a postavi znova. PORADIE: najprv polozka, potom filter -
            // naopak to padne, lebo `deleteMenuItem` si filter este raz nacita.
            def current = getFilterFromMenuItem(existing)
            deleteMenuItem(existing)
            if (current != null) deleteFilter(current)
        }
        createOrUpdateMenuItem(
                id,
                "nastavenia",       // URI cesta - musi sedet s uriNodes
                "Task",
                "transitionId:\"t_sc_nastavenia\" AND processId:\"" +
                        (useCase.petriNetId as String) + "\"",
                "tune",
                nazov,
                [siet],
                ["spravca": siet],  // v menu ju vidi len spravca
                [:])
    } catch (Exception e) {
        // Menu nesmie zhodit zalozenie konfiguracneho casu - bez neho by appka
        // prisla aj o limit, nielen o polozku v menu.
        changeCaseProperty("color").about { "orange" }
    }
}

{ def u ->
    return (u.hasProperty("fullName") && u.fullName) ? (u.fullName as String) : (u.email as String)
}

{ ->
    // Roly su v OBOCH sietiach appky a menia sa naraz - inak by clovek
    // schvaloval faktury strediska, ale objednavky nie.
    return ["schvalovanie/faktury/fa_faktura", "schvalovanie/objednavky/ob_objednavka"]
}

{ ->
    // Kluc pola -> importId roly. Poradie urcuje poradie na formulari.
    return ["sc_hotel"      : "schv_hotel",
            "sc_restauracia": "schv_restauracia",
            "sc_wellness"   : "schv_wellness",
            "sc_udrzba"     : "schv_udrzba",
            "sc_marketing"  : "schv_marketing",
            "sc_sprava"     : "schv_sprava"]
}

{ def sc_limit ->
    // Case sa pri novej verzii siete zaklada nanovo (inak by na nom chybali
    // nove polia). Hodnoty, ktore su UDAJ a nie odraz roli, sa preto musia
    // preniest - bez toho by kazdy re-import ticho vratil limit na default.
    def stary = najnovsiCase("nastavenia/sc_nastavenia")
    def prev = (stary != null && stary.stringId != useCase.stringId)
            ? stary.dataSet["sc_limit"]?.value : null
    change sc_limit value { (prev != null ? prev : 1000.0d) as Double }
}

{ def polia ->
    // Formular ukazuje SKUTOCNY stav roli, nie to, co si niekto naposledy
    // ulozil - roly sa daju zmenit aj v appke Používatelia a obe obrazovky
    // musia hovorit to iste.
    def zoznam = userOptions()
    strediska().each { pole, rola ->
        change polia[pole] options { zoznam }
        change polia[pole] value { usersWithRoleAll(rola, siete()[0]) }
    }
    ["sc_zadavatelia": "zadavatel", "sc_uctovnici": "uctovnik",
     "sc_riaditelia" : "riaditel"].each { pole, rola ->
        change polia[pole] options { zoznam }
        change polia[pole] value { usersWithRoleAll(rola, siete()[0]) }
    }
}

{ def pole, def rola, def riadky ->
    // Nastavenie stavu, nie pridavanie: kto v zozname nie je, rolu strati -
    // inak by sa schvalovatel nedal nikdy odobrat.
    def chceme = ((pole.value ?: []) as List).collect { it as String } as Set
    def maju = [] as Set
    siete().each { siet -> maju.addAll(usersWithRoleAll(rola as String, siet)) }

    def pridane = 0, odobrane = 0
    (chceme - maju).each { uid ->
        siete().each { siet -> setProcessRole(uid as String, rola as String, siet, "", true) }
        pridane++
    }
    (maju - chceme).each { uid ->
        siete().each { siet -> setProcessRole(uid as String, rola as String, siet, "", false) }
        odobrane++
    }
    if (pridane || odobrane) {
        riadky << ((rola as String) + ": +" + pridane + " / -" + odobrane +
                " (spolu " + chceme.size() + ")")
    }
}

actions.action:
sc_hotel: f.sc_hotel, sc_restauracia: f.sc_restauracia, sc_wellness: f.sc_wellness,
sc_udrzba: f.sc_udrzba, sc_marketing: f.sc_marketing, sc_sprava: f.sc_sprava,
sc_zadavatelia: f.sc_zadavatelia, sc_uctovnici: f.sc_uctovnici,
sc_riaditelia: f.sc_riaditelia;

// Pri kazdom otvoreni sa formular naplni zo SKUTOCNEHO stavu roli. Zoznam
// uzivatelov aj hodnoty su runtime data - v `create` udalosti pripadu by sa
// `change ... options` neuchovalo (B11).
nacitaj_stav([sc_hotel      : sc_hotel, sc_restauracia: sc_restauracia,
              sc_wellness   : sc_wellness, sc_udrzba: sc_udrzba,
              sc_marketing  : sc_marketing, sc_sprava: sc_sprava,
              sc_zadavatelia: sc_zadavatelia, sc_uctovnici: sc_uctovnici,
              sc_riaditelia : sc_riaditelia])

sc_limit: f.sc_limit;

def v = sc_limit.value
if (v == null || (v as Number).doubleValue() <= 0) {
    throw new java.lang.IllegalStateException(
            "Limit riaditeľa musí byť väčší ako nula. Ak nemá schvaľovať nič, " +
                    "odoberte mu rolu; nula by znamenala, že schvaľuje všetko.")
}

sc_limit: f.sc_limit, sc_hotel: f.sc_hotel, sc_restauracia: f.sc_restauracia,
sc_wellness: f.sc_wellness, sc_udrzba: f.sc_udrzba, sc_marketing: f.sc_marketing,
sc_sprava: f.sc_sprava, sc_zadavatelia: f.sc_zadavatelia,
sc_uctovnici: f.sc_uctovnici, sc_riaditelia: f.sc_riaditelia,
sc_vysledok: f.sc_vysledok, sc_ulozil: f.sc_ulozil, sc_ulozene_o: f.sc_ulozene_o;

def riadky = []
def polia = [sc_hotel      : sc_hotel, sc_restauracia: sc_restauracia,
             sc_wellness   : sc_wellness, sc_udrzba: sc_udrzba,
             sc_marketing  : sc_marketing, sc_sprava: sc_sprava]

strediska().each { pole, rola -> uloz_rolu(polia[pole], rola, riadky) }
uloz_rolu(sc_zadavatelia, "zadavatel", riadky)
uloz_rolu(sc_uctovnici, "uctovnik", riadky)
uloz_rolu(sc_riaditelia, "riaditel", riadky)

riadky << ("limit riaditeľa: " +
        String.format(java.util.Locale.US, "%.2f", (sc_limit.value as Number).doubleValue()) + " €")
if (riadky.size() == 1) {
    riadky << "roly sa nezmenili"
}
// Kto rolu prave dostal, musí sa odhlásit a prihlásit - prihlasena session
// drzi stare stringId roli a zakladanie casu by vratilo 403.
riadky << "komu sa rola zmenila, nech sa odhlási a prihlási"

change sc_vysledok value { riadky.join("\n") }
change sc_ulozil value { kto(loggedUser()) }
change sc_ulozene_o value { java.time.LocalDateTime.now() }
